  // this wrong hides the implant behind the bone, which is the one thing the
  // page exists to show.
  const HOME = { az: 74, el: 12, zoom: 1, tx: 0, ty: 0 };''')

# 2. Locale-independent numbers. toLocaleString() renders 8.596 as "8,596" in a
#    comma-decimal locale, which reads as 8596 next to a "1,5 mm" limit.
s = s.replace(
  '  const fmt = (v) => (v === null || v === undefined ? "—" : (+v).toLocaleString(undefined, { maximumFractionDigits: 3 }));',
  '''  // Fixed en-US formatting on purpose: a comma-decimal locale turns 8.596 into
  // "8,596", which beside a "1,5 mm" limit reads as three thousand times over.
  const NUM = new Intl.NumberFormat("en-US", { maximumFractionDigits: 3 });
  const fmt = (v) => (v === null || v === undefined ? "\\u2014" : NUM.format(+v));''')

# 3. More contrast in the shading, and a touch of specular on the metal so the
#    two materials read apart at a glance.
s = s.replace(
  '''      const lambert = Math.max(0, nx * LIGHT[0] - ny * LIGHT[1] + nz * LIGHT[2]);
